<?php
declare(strict_types=1);use Vendi\Database\Connection;use Vendi\Http\ApiGuard;use Vendi\Branches\BranchContextService;use Vendi\Branches\BranchClock;
require dirname(__DIR__,3).'/vendor/autoload.php';session_start();header('Content-Type: application/json; charset=utf-8');
try{$u=ApiGuard::session();$db=Connection::make(['host'=>getenv('DB_HOST')?:'127.0.0.1','port'=>(int)(getenv('DB_PORT')?:3306),'database'=>getenv('DB_DATABASE')?:'vendi','username'=>getenv('DB_USERNAME')?:'root','password'=>getenv('DB_PASSWORD')?:'']);$s=new BranchContextService($db);if($_SERVER['REQUEST_METHOD']==='POST'){ApiGuard::csrf();$d=json_decode(file_get_contents('php://input'),true,512,JSON_THROW_ON_ERROR);$s->select($u,(int)($d['branch_id']??0));}$active=$s->active($u);$clock=new BranchClock($db);echo json_encode(['ok'=>true,'active_branch_id'=>$active,'branches'=>$s->available($u),'local_now'=>$clock->now((int)$u['business_id'],$active)->format(DATE_ATOM)],JSON_UNESCAPED_UNICODE);}catch(Throwable$e){http_response_code(in_array((int)$e->getCode(),[401,403],true)?(int)$e->getCode():422);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);}